    ||s.match(/\bwells?\s+((?:[A-Za-z0-9][A-Za-z0-9_.\-]{0,15})(?:\s*(?:,|;|и|and|&)\s*[A-Za-z0-9][A-Za-z0-9_.\-]{0,15})*)/i);
  if(!m) return [];
